// Get failed executions from last 5 minutes
const data = $input.first().json;
const executions = data.data || [];
const now = new Date();
const fiveMinAgo = new Date(now.getTime() - 5 * 60 * 1000);

// Filter to recent failures only, exclude THIS workflow's own executions
const thisWorkflowId = $workflow.id;
const recent = executions.filter(ex => {
  const started = new Date(ex.startedAt || 0);
  return started >= fiveMinAgo && ex.workflowId !== thisWorkflowId;
});

if (recent.length === 0) return [];

// For each failure, build a log entry
const entries = [];
for (const ex of recent) {
  entries.push({
    json: {
      executionId: ex.id || '',
      workflowId: ex.workflowId || '',
      startedAt: ex.startedAt || '',
      status: ex.status || 'error'
    }
  });
}
return entries;

// Parse execution detail and classify the error
const ex = $input.first().json;
const ts = new Date().toISOString();

// Get workflow info
const wfData = ex.workflowData || {};
const wfName = wfData.name || 'Unknown';
const wfId = ex.workflowId || '';
const exId = ex.id || '';

// Extract error info
const rd = (ex.data || {}).resultData || {};
const topErr = rd.error || {};
let errorMessage = topErr.message || '';
let failedNode = topErr.node?.name || '';

// Also check runData for node-level errors
const runData = rd.runData || {};
for (const [nodeName, runs] of Object.entries(runData)) {
  for (const run of runs) {
    if (run.error) {
      if (!failedNode) failedNode = nodeName;
      if (!errorMessage) errorMessage = run.error.message || '';
    }
  }
}

if (!errorMessage) errorMessage = 'Unknown error (check execution log)';
if (!failedNode) failedNode = 'Unknown';

// Classify
const m = (errorMessage || '').toLowerCase();
let cat = 'Unclassified', sev = 'Medium', sol = 'Check execution log.', retry = false;
if (m.includes('401') || m.includes('unauthorized') || m.includes('credential') || m.includes('refresh token') || m.includes('forbidden')) {
  cat = 'Auth Error'; sev = 'Critical'; sol = 'Re-authenticate credential for: ' + failedNode;
} else if (m.includes('429') || m.includes('rate limit')) {
  cat = 'Rate Limit'; sev = 'Medium'; sol = 'Wait and retry.'; retry = true;
} else if (m.includes('timeout') || m.includes('econn') || m.includes('network') || m.includes('socket') || m.includes('502') || m.includes('503') || m.includes('504')) {
  cat = 'Network'; sev = 'Medium'; sol = 'Check service.'; retry = true;
} else if (m.includes('validation') || m.includes('required') || m.includes('undefined') || m.includes('cannot read') || m.includes('has issues')) {
  cat = 'Data/Config Error'; sev = 'High'; sol = 'Check config in: ' + failedNode;
} else if (m.includes('404') || m.includes('not found') || m.includes('does not exist')) {
  cat = 'Not Found'; sev = 'High'; sol = 'Check resource in: ' + failedNode;
} else if (m.includes('500') || m.includes('internal server')) {
  cat = 'Server Error'; sev = 'Medium'; sol = 'Service error.'; retry = true;
} else if (m.includes('permission') || m.includes('access denied')) {
  cat = 'Permission'; sev = 'Critical'; sol = 'Check scopes for: ' + failedNode;
}

const emoji = sev === 'Critical' ? ':red_circle:' : sev === 'High' ? ':large_orange_circle:' : ':large_yellow_circle:';
const slack = emoji + ' *n8n Error*\n*Workflow:* ' + wfName + '\n*Node:* `' + failedNode + '`\n*Type:* ' + cat + ' (' + sev + ')\n```' + (errorMessage||'').substring(0,300) + '```\n*Fix:* ' + sol + '\n<https://n8n.aimanagingservices.com/workflow/' + wfId + '|Workflow> | <https://n8n.aimanagingservices.com/execution/' + exId + '|Execution>';

const sheetRow = JSON.stringify({
  values: [[ts, wfName, wfId, exId, failedNode, cat, sev, (errorMessage||'').substring(0,500), sol, retry?'Yes':'No', retry?'Pending':'Manual Fix', '']]
});

return [{ json: { _slack: slack, _body: sheetRow, _retry: retry, _exId: exId } }];
